"""Collision/identity guard for declared EC Li starts; no electronic calculation."""
from pathlib import Path
import json,math,sys
def read_xyz(path):
    lines=Path(path).read_text(encoding='utf-8').splitlines();n=int(lines[0])
    rows=[s.split() for s in lines[2:2+n]]
    if len(rows)!=n or any(len(r)!=4 for r in rows):raise ValueError('malformed XYZ')
    symbols=[r[0] for r in rows];coords=[[float(v) for v in r[1:]] for r in rows]
    if not all(math.isfinite(v) for row in coords for v in row):raise ValueError('nonfinite XYZ')
    return symbols,coords
def validate(geometry,candidate,parent):
    symbols,c=read_xyz(geometry);ps,pc=read_xyz(parent);r=json.loads(Path(candidate).read_text(encoding='utf-8'))
    if symbols!=ps or symbols.count('Li')!=1:raise ValueError('composition/order mismatch')
    if sum({'C':6,'H':1,'O':8,'Li':3}[s] for s in symbols)-r['charge']!=47 or r['charge']!=2 or r['multiplicity']!=2:raise ValueError('electronic identity mismatch')
    li=symbols.index('Li')
    for i,s in enumerate(symbols):
        if i!=li and max(abs(a-b) for a,b in zip(c[i],pc[i]))>1e-10:raise ValueError('solvent skeleton changed')
    distances={i:math.dist(c[li],row) for i,row in enumerate(c) if i!=li}
    for i,d in distances.items():
        if d<r['contact_floor_A'][symbols[i]]-1e-10:raise ValueError('Li contact collision at atom '+str(i))
    targets=r['target_oxygen_indices_zero_based']
    for i in targets:
        if symbols[i]!='O' or abs(distances[i]-1.95)>1e-8:raise ValueError('target donor distance mismatch')
    for i,d in distances.items():
        if symbols[i]=='O' and i not in targets and d<r['non_target_oxygen_floor_A']:raise ValueError('non-target oxygen overlap')
    return distances
if __name__=='__main__':
    result=validate(*sys.argv[1:]);print(json.dumps({'geometry_preflight':'passed','Li_contacts_A':result},indent=2))
